mutation CreateExchange(
  $filter: String
  $sourceFileId: String!
  $targetExchangeName: String!
  $targetFolderId: String!
) {
  createExchange(
    input: {
      filter: $filter
      source: { fileId: $sourceFileId }
      target: { name: $targetExchangeName, folderId: $targetFolderId }
    }
  ) {
    exchange {
      id
      name
      elements {
        results {
          id
          name
        }
      }
    }
  }
}

