query GetExchangeStatus($exchangeId: ID!) {
  getExchangeCreationStatus(exchangeId: $exchangeId) {
    status
    versionNumber
    exchange {
      id
      name
      elements {
        results {
          id
          name
        }
      }
    }
  }
}

